def header(dir):
   return magic_number + struct.pack("<HBBI",version,width,height,dir)

# this will give me the directiive payload for top bottom let and right border
def handler(x,y,w,h):
    payload = b""
    for i in range(y,h+y):
        for j in range(x,w+x):
            p = pixel[width*i+j]
            payload += struct.pack("BBBB",p[0],p[1],p[2],ord(p[3]))
    return  struct.pack("<HBBBB",code2,x,y,w,h)+payload  


def optimized_handler_logo():
    actual_payload = []
    for i in range(1,height-1):
        j = 1
        while j < (width -1):
            pi = pixel[width * i + j]
            if pi[3] == " ":
                j += 1
                continue
            new = j
            data = []
            while j < (width-1):
                pi = pixel[width * i + j]
                if pi[3] == " ":
                    if (j+1) < (width - 1) and pixel[width * i + (j+1)][3] != " ":
                        data.append(pi)
                        j += 1
                        continue
                    else:
                        break
                data.append(pi)
                j += 1
            actual_payload.append(handler(new,i,len(data),1))
    return actual_payload

top = handler(0,0,width,1)
left = handler(0,1,1,22)
bottom = handler(0,height-1,width,1)
right = handler(width-1,1,1,22)

logo_part = optimized_handler_logo()
#c = handler(23,10,6,4)
#I = handler(30,9,5,5)
#M = handler(36,9,8,5)
#G = handler(45,9,7,5)

payload = header(4+len(logo_part))+top+left+right+bottom

for p in logo_part:
    payload += p

print("Length of image: ",len(payload))
print("No of directive used: ",4+len(logo_part))

with open('image1.cimg','wb') as file:
    file.write(payload)


